async function finalRush() {
    const targets = ['Butterfly', 'Chicken', 'Cow', 'Goblin', 'Imp', 'Bear', 'Giant rat'];
    for (const targetName of targets) {
        const res = await bot.attack(targetName);
        if (res.success) {
            while (sdk.getState()?.player?.combat.inCombat) {
                if (sdk.getState()?.player?.hp < 10) {
                    await bot.eatFood();
                }
                await sdk.waitForStateUpdate();
            }
        }
    }
}
